public function getRelationFilterCondition(?string $value, string $operator, string $name): string
{
    if ($operator === '=') {
        return '`' . $name . '` = ' . "'" . $value . "'";
    }

    return implode(' AND ', array_map(
        fn ($v) => '`' . $name . "` LIKE '%," . $v . ",%'",
        array_filter(explode(',', $value))
    ));
}

