function save_page(array &$page): bool
{
    $slug = trim($page['slug'] ?? '');
    if ($slug === '') {
        $slug = slugify($page['title'] ?? '');
    }

    $path = PAGES_PATH . '/' . $slug . '.md';

    return file_put_contents($path, $page['content'] ?? '') !== false;
}

